     {zh:'虽然不是上下班高峰期，这里照样堵车。',py:'Suīrán bú shì shàng xià bān gāofēngqī, zhèlǐ zhàoyàng dǔchē.',vn:'Tuy không phải giờ cao điểm, chỗ này vẫn cứ tắc đường.'},
     {zh:'他发着烧，照样来上课了。',py:'Tā fāzhe shāo, zhàoyàng lái shàngkè le.',vn:'Cậu ấy đang sốt mà vẫn đến lớp như thường.'}
