// ══════════════════════════════════════════
var dialogData = [
  {scene:'课文 · 全球化视野中的中国饮食',
   preQuiz:[
     {q:'中国饮食文化始终具有魅力，是因为什么？',opts:['民族特性鲜明，又善于吸收别人的优异之处','历史最悠久，从来不改变','食物价格便宜'],ans:0},
     {q:'作者认为，中国文化的核心是哪个字？',opts:['“和”','“食”','“新”'],ans:0},
     {q:'“中和”是什么意思？',opts:['把性质相同的东西放在一起','折中、调和性质不同的事物','只吃中国本地的食物'],ans:1},
     {q:'经过精心构思、巧妙烹饪，即便仅为一餐素食，也能怎么样？',opts:['比肉更贵','让人吃不饱','让你尽享人间美味'],ans:2},
     {q:'什么时候，中亚及东南亚的食物进入了中华饮食体系？',opts:['先秦时期','汉唐以后','近代'],ans:1},
     {q:'近代，中华饮食发生了什么变化？',opts:['西方饮食思想与方式得到认可','不再吃外来食物','人们开始跪坐而食'],ans:0},
     {q:'在食材栽培方面，中华饮食坚持以什么为基本原料？',opts:['外来品种','本国物产','进口调料'],ans:1},
     {q:'历史不够悠久的外来食品，人们一般怎样分辨出来？',opts:['从颜色上','从价格上','从食物名称上'],ans:2},
     {q:'为什么许多中国人把葱、姜、蒜当成正宗的中国食材？',opts:['因为它们进入中华饮食年代久远','因为它们最便宜','因为只有中国才有'],ans:0},
     {q:'外来食材能被改变为中国饮食成分，得力于什么？',opts:['政府的规定','中国人认识其内在价值，并有开放的思维和灵感','外国厨师的帮助'],ans:1},
     {q:'先秦至唐代，中国人采用什么方式就餐？',opts:['围坐合餐','自助餐','分餐式'],ans:2},
     {q:'“合餐制”是怎样形成的？',opts:['胡床和较大的餐桌在中原流行，打破了跪坐而食的局限','西方饮食思想传入中国','皇帝下令大家一起吃饭'],ans:0},
     {q:'作者认为中华饮食文化充满活力的奥秘是什么？',opts:['只继承传统，从不改变','面向世界，边继承边改革，不断引进新元素','完全学习西方的饮食'],ans:1}
   ],
   lines:[
    {sp:0,zh:'任何一个民族的饮食都不仅仅为饮食，它蕴藏着这个民族的精神与特征，传达着这个民族的文化传统。中国的饮食文化历经数千年，始终具有魅力，是因为它不仅民族特性鲜明，而且善于吸收不同国家、不同区域、不同民族的优异之处，以至辉煌至今。',
     py:'Rènhé yí ge mínzú de yǐnshí dōu bù jǐnjǐn wéi yǐnshí, tā yùncángzhe zhège mínzú de jīngshén yǔ tèzhēng, chuándázhe zhège mínzú de wénhuà chuántǒng. Zhōngguó de yǐnshí wénhuà lìjīng shù qiān nián, shǐzhōng jùyǒu mèilì, shì yīnwèi tā bùjǐn mínzú tèxìng xiānmíng, érqiě shànyú xīshōu bù tóng guójiā, bù tóng qūyù, bù tóng mínzú de yōuyì zhī chù, yǐzhì huīhuáng zhì jīn.',
     vn:'Ẩm thực của bất kỳ dân tộc nào cũng không chỉ đơn thuần là chuyện ăn uống, nó chứa đựng tinh thần và đặc trưng của dân tộc ấy, truyền tải truyền thống văn hoá của dân tộc ấy. Văn hoá ẩm thực Trung Quốc trải qua mấy nghìn năm mà vẫn luôn có sức hấp dẫn, là bởi nó không những mang bản sắc dân tộc rõ nét, mà còn giỏi tiếp thu những điểm ưu tú của các quốc gia, các khu vực, các dân tộc khác nhau, nhờ vậy mà huy hoàng cho đến tận hôm nay.'},
    {sp:0,zh:'中国文化的核心是一个“和”字。“和”包含“中和”“和谐”之意。“中和”的意思就是折中、调和性质不同的事物。',
     py:'Zhōngguó wénhuà de héxīn shì yí ge "hé" zì. "Hé" bāohán "zhōnghé" "héxié" zhī yì. "Zhōnghé" de yìsi jiù shì zhézhōng, tiáohé xìngzhì bù tóng de shìwù.',
     vn:'Cốt lõi của văn hoá Trung Quốc là một chữ "hoà". "Hoà" bao hàm ý "trung hoà" và "hài hoà". "Trung hoà" nghĩa là dung hoà, điều hoà những sự vật có tính chất khác nhau.'},
    {sp:0,zh:'原本中华饮食中的大量食物来自辽阔的土地，高山上的飞禽走兽，湖泊、小溪中的一条鱼，丘陵上种植的一棵菜，经过精心构思，巧妙烹饪，即便仅为一餐素食，也可以让你尽享人间美味。汉唐以后，中亚及东南亚的食物进入了中华饮食体系，极大地丰富了中国食物的品种；近代，西方饮食思想与方式得到认可，具有现代特征的中华饮食形态逐渐形成。',
     py:'Yuánběn Zhōnghuá yǐnshí zhōng de dàliàng shíwù láizì liáokuò de tǔdì, gāoshān shang de fēiqín zǒushòu, húpō, xiǎoxī zhōng de yì tiáo yú, qiūlíng shang zhòngzhí de yì kē cài, jīngguò jīngxīn gòusī, qiǎomiào pēngrèn, jíbiàn jǐn wéi yì cān sùshí, yě kěyǐ ràng nǐ jìnxiǎng rénjiān měiwèi. Hàn Táng yǐhòu, Zhōngyà jí Dōngnányà de shíwù jìnrùle Zhōnghuá yǐnshí tǐxì, jí dà de fēngfùle Zhōngguó shíwù de pǐnzhǒng; jìndài, xīfāng yǐnshí sīxiǎng yǔ fāngshì dédào rènkě, jùyǒu xiàndài tèzhēng de Zhōnghuá yǐnshí xíngtài zhújiàn xíngchéng.',
     vn:'Vốn dĩ, phần lớn thực phẩm trong ẩm thực Trung Hoa đến từ vùng đất bao la: chim muông thú vật trên núi cao, một con cá dưới hồ, dưới suối, một cây rau trồng trên đồi — qua ý tưởng tỉ mỉ, nấu nướng khéo léo, cho dù chỉ là một bữa chay cũng có thể khiến bạn tận hưởng mỹ vị nhân gian. Sau thời Hán, Đường, thực phẩm của Trung Á và Đông Nam Á đi vào hệ thống ẩm thực Trung Hoa, làm phong phú thêm rất nhiều chủng loại thực phẩm Trung Quốc; đến thời cận đại, tư tưởng và cách thức ăn uống phương Tây được chấp nhận, hình thái ẩm thực Trung Hoa mang đặc trưng hiện đại dần dần hình thành.'},
    {sp:0,zh:'在食材栽培方面，中华饮食坚持以本国物产为基本原料，同时合理引进、培育外来品种，比如咖啡、柠檬、芒果等，凡是历史不够悠久的外来食品，人们一般从食物名称上就能立即清晰地分辨出它的洋身份。至于中餐中使用频率最高的葱、姜、蒜等调料，因其进入中华饮食年代久远，许多中国人甚至把它当成了正宗的中国食材。在加工过程中，中国人照样可以用中国方式烹饪外来食材，使它美味诱人。而这一切得力于中国人能够充分认识异域食物的内在价值，以开放性的思维和灵感，创新式地把外来食物改变为中国饮食成分。',
     py:'Zài shícái zāipéi fāngmiàn, Zhōnghuá yǐnshí jiānchí yǐ běnguó wùchǎn wéi jīběn yuánliào, tóngshí hélǐ yǐnjìn, péiyù wàilái pǐnzhǒng, bǐrú kāfēi, níngméng, mángguǒ děng, fánshì lìshǐ bú gòu yōujiǔ de wàilái shípǐn, rénmen yìbān cóng shíwù míngchēng shang jiù néng lìjí qīngxī de fēnbiàn chū tā de yáng shēnfèn. Zhìyú zhōngcān zhōng shǐyòng pínlǜ zuì gāo de cōng, jiāng, suàn děng tiáoliào, yīn qí jìnrù Zhōnghuá yǐnshí niándài jiǔyuǎn, xǔduō Zhōngguórén shènzhì bǎ tā dàngchéngle zhèngzōng de Zhōngguó shícái. Zài jiāgōng guòchéng zhōng, Zhōngguórén zhàoyàng kěyǐ yòng Zhōngguó fāngshì pēngrèn wàilái shícái, shǐ tā měiwèi yòurén. Ér zhè yíqiè délì yú Zhōngguórén nénggòu chōngfèn rènshi yìyù shíwù de nèizài jiàzhí, yǐ kāifàngxìng de sīwéi hé línggǎn, chuàngxīn shì de bǎ wàilái shíwù gǎibiàn wéi Zhōngguó yǐnshí chéngfèn.',
     vn:'Về mặt trồng trọt nguyên liệu, ẩm thực Trung Hoa kiên trì lấy sản vật trong nước làm nguyên liệu cơ bản, đồng thời hợp lý nhập về và gây giống những giống ngoại lai như cà phê, chanh, xoài…; phàm là thực phẩm ngoại lai có lịch sử chưa đủ lâu đời, người ta thường nhìn tên gọi là lập tức phân biệt rõ ràng "gốc ngoại" của nó. Còn các gia vị được dùng nhiều nhất trong món Trung như hành, gừng, tỏi, vì đã đi vào ẩm thực Trung Hoa từ rất lâu đời nên nhiều người Trung Quốc thậm chí coi chúng là nguyên liệu chính gốc Trung Quốc. Trong quá trình chế biến, người Trung Quốc vẫn có thể nấu nguyên liệu ngoại lai theo cách của Trung Quốc, khiến chúng thơm ngon hấp dẫn. Mà tất cả những điều này là nhờ người Trung Quốc có thể nhận thức đầy đủ giá trị nội tại của thực phẩm nước ngoài, bằng tư duy cởi mở và cảm hứng sáng tạo, đã một cách sáng tạo biến thực phẩm ngoại lai thành một phần của ẩm thực Trung Quốc.'},
    {sp:0,zh:'在就餐方式上，中华饮食文化同样显示着不排斥异域文化的态度，比如中餐“合餐制”的形成。先秦至唐代，中国采用分餐式方式就餐。南北朝时期，一种可随意折起来、称作胡床的坐具和一种较大的餐桌开始在中原地区流行，这些器具的推广，打破了跪坐而食的局限，形成了围坐合餐的形式。当然，对“合餐制”的全面接受与文化认同，根本上与“和”文化是相通的。',
     py:'Zài jiùcān fāngshì shang, Zhōnghuá yǐnshí wénhuà tóngyàng xiǎnshìzhe bù páichì yìyù wénhuà de tàidu, bǐrú zhōngcān "hécānzhì" de xíngchéng. Xiān Qín zhì Táng dài, Zhōngguó cǎiyòng fēncān shì fāngshì jiùcān. Nánběicháo shíqī, yì zhǒng kě suíyì zhé qǐlái, chēngzuò húchuáng de zuòjù hé yì zhǒng jiào dà de cānzhuō kāishǐ zài Zhōngyuán dìqū liúxíng, zhèxiē qìjù de tuīguǎng, dǎpòle guìzuò ér shí de júxiàn, xíngchéngle wéizuò hécān de xíngshì. Dāngrán, duì "hécānzhì" de quánmiàn jiēshòu yǔ wénhuà rèntóng, gēnběn shang yǔ "hé" wénhuà shì xiāngtōng de.',
     vn:'Về cách thức dùng bữa, văn hoá ẩm thực Trung Hoa cũng thể hiện thái độ không bài xích văn hoá nước ngoài, chẳng hạn như sự hình thành "chế độ ăn chung" của người Trung Quốc. Từ thời Tiên Tần đến đời Đường, người Trung Quốc dùng bữa theo kiểu chia suất riêng. Thời Nam Bắc triều, một loại đồ ngồi có thể tuỳ ý gập lại gọi là "hồ sàng" cùng một loại bàn ăn khá lớn bắt đầu thịnh hành ở vùng Trung Nguyên; việc phổ biến những đồ dùng này đã phá vỡ giới hạn ngồi quỳ mà ăn, hình thành nên hình thức ngồi quây quần ăn chung. Đương nhiên, việc tiếp nhận toàn diện và đồng thuận về văn hoá đối với "chế độ ăn chung", về căn bản là tương thông với văn hoá "hoà".'},
    {sp:0,zh:'可以说，中华饮食文化自诞生之日起，就面向世界，边继承，边改革，不断引进新元素，这也是其充满活力的奥秘所在。',
     py:'Kěyǐ shuō, Zhōnghuá yǐnshí wénhuà zì dànshēng zhī rì qǐ, jiù miànxiàng shìjiè, biān jìchéng, biān gǎigé, búduàn yǐnjìn xīn yuánsù, zhè yě shì qí chōngmǎn huólì de àomì suǒzài.',
     vn:'Có thể nói, văn hoá ẩm thực Trung Hoa ngay từ ngày ra đời đã hướng ra thế giới, vừa kế thừa vừa cải cách, không ngừng đưa vào những yếu tố mới — đó cũng chính là bí quyết giúp nó luôn tràn đầy sức sống.'}
   ]}
];

